import math

from zipf import generate_counts, fit_zipf, ols_fit


def test_ols_tiny_exact():
    slope, intercept, r2 = ols_fit([(0.0, 0.0), (1.0, 2.0), (2.0, 4.0)])
    assert math.isclose(slope, 2.0)
    assert math.isclose(intercept, 0.0)
    assert math.isclose(r2, 1.0)


def test_slope_in_range_for_seeds():
    for seed in (1, 2, 3):
        counts = generate_counts(seed)
        slope, intercept, r2 = fit_zipf(counts)
        assert -1.15 <= slope <= -0.85, f"seed={seed} slope={slope}"
        assert r2 >= 0.98, f"seed={seed} r2={r2}"


def test_counts_monotone_non_increasing():
    for seed in (1, 2, 3):
        counts = sorted(generate_counts(seed), reverse=True)
        for a, b in zip(counts, counts[1:]):
            assert a >= b

